        HttpResponse<String> withoutCode = post("/reservations", corporate);
        assertEquals(400, withoutCode.statusCode());
        assertEquals("INVALID_REQUEST", json.readTree(withoutCode.body()).get("error").asText());
    }

    @Test
    void ignoresTheCompanyCodeInOtherPlans() throws Exception {
        HttpResponse<String> created = post("/reservations",
                RESERVATION_JSON.replace("\"guests\": 2", "\"guests\": 2, \"companyCode\": \"TECNOSUL\""));

        assertEquals(201, created.statusCode());
        assertEquals(935.76, json.readTree(created.body()).get("total").asDouble());
    }
}
